    categories:["Sixth Army","Red Army armies","Battle of Uman","Southwestern Front","Operation Barbarossa"],
    facts:[["Formation represented","First formation <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Formed","1939 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Active army through divergence","22 June–31 July 1941 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Commander on 31 July","Lieutenant General Ivan Muzychenko <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Initial superior command","Southwestern Front <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Transferred","Southern Front · 25 July 1941 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Initial axis","Lviv <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Status on 31 July","Threatened near Uman <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Historical August result","Not inherited automatically <sup class='canon-note' data-provenance='e'>[e]</sup>"],["Later formation","Open <sup class='canon-note' data-provenance='e'>[e]</sup>"]]
